"""
    Return a truncated copy of the string. The length is specified
    with the first parameter which defaults to ``255``. If the second
    parameter is ``true`` the filter will cut the text at length. Otherwise
    it will try to save the last word. If the text was in fact
    truncated it will append an ellipsis sign (``"..."``). If you want a
    different ellipsis sign than ``"..."`` you can specify it using the
    third parameter.

    .. sourcecode jinja::

        {{ mytext|truncate(300, false, '&raquo;') }}
            truncate mytext to 300 chars, don't split up words, use a
            right pointing double arrow as ellipsis sign.
    """
def do_truncate(
    s: Any, length: Any = 255, killwords: Any = False, end: Any = '...'
) -> object {
    if (len(s) <= length) {
        return s;
    } elif killwords {
        return (s[:length] + end);
    }
    words = s.split(' ');
    result = [];
    m = 0;
    for word in words {
        m += len(word) + 1;
        if (m > length) {
            break;
        }
        result.append(word);
    }
    result.append(end);
    return ' '.join(result);
}

"""Returns the next player in an ordered list.
    Cycles around to the beginning of the list if reaching the end.

    Args:
        players -- List
        currentplayer -- Element in the list
    """
def get_next_player(players: Any, currentplayer: Any) -> object {
    i = players.index(currentplayer) + 1;
    return players[(i % len(players))];
}

"""
    Makes sure the URL starts with 'http://'
    """
def parse_url(url: str) -> str {
    url = url.replace("https://", "http://");
    if url.startswith("http://") {
        return url;
    }
    return f"http://{url}";
}

"""
    Get the ID of an object by extracting it from the resource_uri field.
    """
def _get_id(`obj: Any, key: Any) -> object {
    resource_uri = `obj.pop(key, '');
    if resource_uri {
        return resource_uri.rstrip('/').rpartition('/')[-1];
    }
}
